score_methods <- function(industry=NULL, problem_type=NULL, data_type=NULL,
                          data_volume=NULL, latency=NULL, serving=NULL,
                          interpretability=NULL, team_maturity=NULL) {
  scores <- sapply(ML_MODELS, function(m) {
    s <- 0
    if(!is.null(industry)         && industry         %in% m$industries)       s <- s + 3
    if(!is.null(problem_type)     && problem_type     %in% m$problem_types)    s <- s + 3
    if(!is.null(data_type)        && data_type        %in% m$data_types)       s <- s + 2
    if(!is.null(data_volume)      && data_volume      %in% m$data_volume)      s <- s + 2
    if(!is.null(latency)          && latency          %in% m$latency)          s <- s + 2
    if(!is.null(serving)          && serving          %in% m$serving)          s <- s + 1
    if(!is.null(interpretability) && interpretability %in% m$interpretability) s <- s + 2
    if(!is.null(team_maturity)    && team_maturity    %in% m$team_maturity)    s <- s + 1
    s
  })
  idx <- order(scores, decreasing=TRUE)
  list(top3=ML_MODELS[idx[1:min(3,length(idx))]], all=ML_MODELS[idx], scores=scores[idx])
}
